<?php
declare(strict_types=1); require __DIR__.'/bootstrap.php';
if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){sf_admin_require_auth(false);$d=sf_admin_knowledge_index();sf_json_response(['ok'=>true,'knowledge'=>$d]);}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')sf_json_response(['ok'=>false,'error'=>'method_not_allowed'],405);sf_admin_require_auth(true);$b=sf_request_json();$a=(string)($b['action']??'');$d=sf_admin_knowledge_index();
if($a==='folder_create'){$name=sf_clean_text($b['name']??'',120);if($name==='')sf_json_response(['ok'=>false,'message'=>'Folder name is required.'],422);$id='KF-'.strtoupper(bin2hex(random_bytes(4)));$d['folders'][]=['id'=>$id,'name'=>$name,'created_at'=>gmdate('c'),'updated_at'=>gmdate('c')];sf_admin_write_knowledge($d);sf_json_response(['ok'=>true,'knowledge'=>$d]);}
