if($a==='file_delete'){$id=(string)($b['id']??'');foreach($d['files'] as $f)if(($f['id']??'')===$id&&!empty($f['stored_path']))@unlink(SF_ROOT.'/'.ltrim((string)$f['stored_path'],'/'));$d['files']=array_values(array_filter($d['files'],fn($f)=>(string)($f['id']??'')!==$id));sf_admin_write_knowledge($d);sf_json_response(['ok'=>true,'knowledge'=>$d]);}
